  const $ = id => document.getElementById(id);
  const STORE = "erazure-rune-odds";
  const N = DATA.runes.length;
  const [LO, HI] = DATA.rateRange;
  const dec = s => { const v = []; for (let i = 0; i < s.length; i += 3) { const c = parseInt(s.slice(i, i + 3), 36);
    v.push(c ? Math.pow(10, LO + (c - 1) * (HI - LO) / (36 ** 3 - 2)) : 0); } return v; };
  const memo = new Map(), V = s => { if (!memo.has(s)) memo.set(s, dec(s)); return memo.get(s); };
  const DIFF = ["Normal", "Nightmare", "Hell"];
  // a place as the lists write it; a Corrupted Zone's spot (group 3, monsters level 85) says so, or it read as the plain
  // Hell area beside it with better odds (the additions audit, 2026-11-23)
  const whereOf = s => [DIFF[s[2]], s[1]].filter(Boolean).join(", ") + (s[3] === 3 ? " as a Corrupted Zone" : "");
  const UNIT = {kill: "a kill", run: "a run", vault: "a vault", map: "a map", dungeon: "a dungeon"};
